package com.fifotech.task.service;
import com.fifotech.task.domain.*; import com.fifotech.task.dto.ApiDtos.*; import com.fifotech.task.exception.ApiException; import com.fifotech.task.repository.UserRepository; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional public class UserService {
 private final UserRepository users;private final PasswordEncoder encoder;
 public UserService(UserRepository users,PasswordEncoder encoder){this.users=users;this.encoder=encoder;}
 public Page<UserResponse> list(String q,int page,int size){Pageable p=PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100),Sort.by("id").ascending());return (q==null||q.isBlank()?users.findAll(p):users.findByFullNameContainingIgnoreCaseOrEmailContainingIgnoreCase(q,q,p)).map(this::view);}
 public UserResponse get(Long id){return view(find(id));}
 public List<UserResponse> team(User actor){List<User> members=actor.getRole()==Role.ADMIN?users.findByRoleAndActiveTrue(Role.EMPLOYEE):users.findByManagerIdAndActiveTrue(actor.getId());return members.stream().filter(u->u.getRole()==Role.EMPLOYEE).map(this::view).toList();}
 public UserResponse create(UserRequest request){if(request.password()==null||request.password().length()<8)throw new ApiException(HttpStatus.BAD_REQUEST,"Password must contain at least 8 characters");if(users.existsByEmailIgnoreCase(request.email()))throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");User manager=managerFor(request.role(),request.managerId());User u=new User(request.fullName().trim(),request.email().trim().toLowerCase(),encoder.encode(request.password()),request.role(),manager);if(request.active()!=null)u.setActive(request.active());return view(users.save(u));}
 public UserResponse update(Long id,UserRequest request){User u=find(id);Role oldRole=u.getRole();if(request.fullName()!=null&&!request.fullName().isBlank())u.setFullName(request.fullName().trim());if(request.email()!=null&&!request.email().isBlank()){String email=request.email().trim().toLowerCase();users.findByEmailIgnoreCase(email).filter(other->!other.getId().equals(id)).ifPresent(other->{throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");});u.setEmail(email);}if(request.password()!=null&&!request.password().isBlank())u.setPassword(encoder.encode(request.password()));if(request.role()!=null)u.setRole(request.role());if(request.managerId()!=null||u.getRole()!=Role.EMPLOYEE||oldRole!=u.getRole())u.setManager(managerFor(u.getRole(),request.managerId()));if(request.active()!=null)u.setActive(request.active());return view(users.save(u));}
 public void delete(Long id){User user=find(id);if(user.getRole()==Role.MANAGER&&!users.findByManagerIdAndActiveTrue(id).isEmpty())throw new ApiException(HttpStatus.CONFLICT,"Reassign or deactivate this manager's employees before deleting the manager");user.setActive(false);users.save(user);}
 private User managerFor(Role role,Long managerId){if(role!=Role.EMPLOYEE){if(managerId!=null)throw new ApiException(HttpStatus.BAD_REQUEST,"Only employees can be assigned to a manager");return null;}if(managerId==null)throw new ApiException(HttpStatus.BAD_REQUEST,"An employee must belong to a manager");User manager=find(managerId);if(manager.getRole()!=Role.MANAGER||!manager.isActive())throw new ApiException(HttpStatus.BAD_REQUEST,"Select an active manager");return manager;}
 private User find(Long id){return users.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"User not found"));}
 public UserResponse view(User u){return new UserResponse(u.getId(),u.getFullName(),u.getEmail(),u.getRole(),u.getManager()==null?null:u.getManager().getId(),u.getManager()==null?null:u.getManager().getFullName(),u.isActive(),u.getCreatedAt());}
}
